-- Generated by GMConverter. The client runtime for converted particle effects that Source's particle
-- system can't draw, such as mesh particles whose texture slides over their life. Effects register
-- their emitters with RegisterEffect; models register the effects their animations start with
-- RegisterModel. View models are watched each frame: when a sequence passes an event's time, the
-- effect starts at that attachment and is drawn with the view model. Every add-on GMConverter writes
-- ships this same file; the newest version loaded wins.

local VERSION = 1

if GMConverterEffects and (GMConverterEffects.version or 0) >= VERSION then return end

local FX = GMConverterEffects or {}
GMConverterEffects = FX
FX.version = VERSION
FX.effects = FX.effects or {}
FX.models = FX.models or {}

-- name -> { emitters = { { model, material, delay, life = { min, max }, bursts = { { time, count } },
-- rate, duration, size = { x, y, z }, color = { { t, r, g, b } }, alpha = { { t, a } },
-- uvScale = { u, v }, uvOffset = { { t, u, v } }, localSpace, additive } } }
function FX.RegisterEffect(name, definition)
	FX.effects[name] = definition
end

-- model path -> { [sequence name] = { { time, effect, attachment }, ... } }
function FX.RegisterModel(model, sequences)
	FX.models[string.lower(model)] = sequences
end

-- Linear interpolation through { { t, a, b, ... } } keys, held past the ends.
local function sample(keys, t)
	if not keys or #keys == 0 then return nil end
	if t <= keys[1][1] then return keys[1] end
	for i = 2, #keys do
		local b = keys[i]
		if t <= b[1] then
			local a = keys[i - 1]
			local span = b[1] - a[1]
			local f = span > 0 and (t - a[1]) / span or 1
			local out = { t }
			for c = 2, #a do out[c] = a[c] + (b[c] - a[c]) * f end
			return out
		end
	end
	return keys[#keys]
end

local models = {}
local function renderModel(path)
	local model = models[path]
	if not IsValid(model) then
		model = ClientsideModel(path, RENDERGROUP_TRANSLUCENT)
		if not IsValid(model) then return nil end
		model:SetNoDraw(true)
		models[path] = model
	end
	return model
end

local materials = {}
local function material(path)
	materials[path] = materials[path] or Material(path)
	return materials[path]
end

-- Particles of one emitter of a started effect: when each is born and how long it lives.
local function spawnParticles(emitter)
	local particles = {}
	for _, burst in ipairs(emitter.bursts or {}) do
		for _ = 1, burst[2] do
			particles[#particles + 1] = { born = emitter.delay + burst[1], life = math.Rand(emitter.life[1], emitter.life[2]) }
		end
	end
	if (emitter.rate or 0) > 0 and (emitter.duration or 0) > 0 then
		for i = 0, math.floor(emitter.rate * emitter.duration) - 1 do
			particles[#particles + 1] = { born = emitter.delay + i / emitter.rate, life = math.Rand(emitter.life[1], emitter.life[2]) }
		end
	end
	return particles
end

local active = {}

local function start(vm, effectName, attachmentName)
	local effect = FX.effects[effectName]
	if not effect then return end
	local attachment = vm:LookupAttachment(attachmentName or "")
	local instance = { vm = vm, effect = effect, started = CurTime(), attachment = attachment, emitters = {} }
	for i, emitter in ipairs(effect.emitters) do
		instance.emitters[i] = spawnParticles(emitter)
	end
	active[#active + 1] = instance
end

local function frame(vm, attachment)
	if attachment and attachment > 0 then
		local point = vm:GetAttachment(attachment)
		if point then return point.Pos, point.Ang end
	end
	return vm:GetPos(), vm:GetAngles()
end

local function drawParticle(emitter, particle, age, pos, ang)
	local t = age / particle.life
	local model = renderModel(emitter.model)
	if not model then return end
	local mat = material(emitter.material)

	local scale = Matrix()
	scale:Scale(Vector(emitter.size[1], emitter.size[2], emitter.size[3]))
	model:EnableMatrix("RenderMultiply", scale)
	model:SetPos(pos)
	model:SetAngles(ang)
	model:SetupBones()

	local transform = Matrix()
	local offset = sample(emitter.uvOffset, t)
	if offset then transform:Translate(Vector(offset[2], offset[3], 0)) end
	transform:Scale(Vector(emitter.uvScale[1], emitter.uvScale[2], 1))
	mat:SetMatrix("$basetexturetransform", transform)

	local color = sample(emitter.color, t) or { t, 1, 1, 1 }
	local alpha = math.Clamp((sample(emitter.alpha, t) or { t, 1 })[2], 0, 1)
	-- Additive glows fade by darkening; blended ones by their alpha.
	local fade = emitter.additive and alpha or 1
	render.SetColorModulation(color[2] * fade, color[3] * fade, color[4] * fade)
	render.SetBlend(emitter.additive and 1 or alpha)
	render.MaterialOverride(mat)
	model:DrawModel()
	render.MaterialOverride()
	render.SetBlend(1)
	render.SetColorModulation(1, 1, 1)
end

local watched = setmetatable({}, { __mode = "k" })

-- Starts the effects a view model's sequence passed since the last frame.
local function watch(vm)
	local events = FX.models[string.lower(vm:GetModel() or "")]
	if not events then return end
	local sequence = vm:GetSequence()
	local time = vm:GetCycle() * vm:SequenceDuration(sequence)
	local last = watched[vm]
	local from = (last and last.sequence == sequence and last.time <= time) and last.time or -1
	watched[vm] = { sequence = sequence, time = time }
	for _, event in ipairs(events[vm:GetSequenceName(sequence)] or {}) do
		if event[1] > from and event[1] <= time then
			start(vm, event[2], event[3])
		end
	end
end

-- Draws one particle if it's alive; returns whether it is still to come or alive.
local function drawIfAlive(emitter, particle, age, pos, ang)
	if age >= particle.life then return false end
	if age < 0 then return true end
	-- Particles outside local space stay where they were born.
	if not emitter.localSpace then
		particle.pos = particle.pos or pos
		particle.ang = particle.ang or ang
	end
	drawParticle(emitter, particle, age, particle.pos or pos, particle.ang or ang)
	return true
end

-- Draws an effect started on this view model; returns whether any of it is still to come or alive.
local function drawInstance(instance, vm, now)
	local pos, ang = frame(vm, instance.attachment)
	local alive = false
	for e, emitter in ipairs(instance.effect.emitters) do
		for _, particle in ipairs(instance.emitters[e]) do
			alive = drawIfAlive(emitter, particle, now - instance.started - particle.born, pos, ang) or alive
		end
	end
	return alive
end

hook.Add("PostDrawViewModel", "GMConverterEffects", function(vm)
	if not IsValid(vm) then return end
	watch(vm)
	local now = CurTime()
	for i = #active, 1, -1 do
		local instance = active[i]
		local alive = IsValid(instance.vm) and (instance.vm ~= vm or drawInstance(instance, vm, now))
		if not alive then table.remove(active, i) end
	end
end)
